@extends('superadmin.layout', ['title' => 'Version Management', 'active' => 'versions'])
@section('content')<div class="superadmin-heading"><div><p class="superadmin-eyebrow">Release Operations</p><h1>Version Management</h1></div><button class="sa-button" onclick="createVersion()">New release</button></div><div id="notice" class="sa-notice"></div><section class="sa-card sa-section"><div class="sa-section-header"><div><h2>Release history</h2><p>{{ $versions->total() }} releases</p></div><form method="GET"><input name="q" value="{{ $filters['search'] ?? '' }}" class="sa-input" placeholder="Search version"><button class="sa-button secondary" type="submit">Filter</button></form></div><div class="sa-table-wrap"><table class="sa-table"><thead><tr><th>Version</th><th>Title</th><th>Release date</th><th>Flags</th><th>Actions</th></tr></thead><tbody>@forelse($versions as $version)<tr><td><strong>{{ $version->version }}</strong></td><td>{{ $version->title }}</td><td>{{ $version->release_date ?: '—' }}</td><td>@if($version->important) Important @endif @if($version->force_refresh) Force refresh @endif</td><td><button class="sa-button danger" onclick="deleteVersion({{ $version->id }})">Delete</button></td></tr>@empty<tr><td colspan="5" class="sa-empty">No releases.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $versions->links() }}</div></section>@endsection
@push('scripts')<script>async function createVersion(){const version=prompt('Version');if(!version)return;const title=prompt('Release title');if(!title)return;await dfApi('{{ route('superadmin.versions.store') }}',{method:'POST',body:{version,title,changelog:'',release_date:new Date().toISOString().slice(0,10),important:false,force_refresh:false}});window.location.reload();}async function deleteVersion(id){if(confirm('Delete release?')){await dfApi(`/superadmin/versions/${id}`,{method:'DELETE'});window.location.reload();}}</script>@endpush
